I will expand the `services/calculator.test.ts` file to include comprehensive coverage for all scoring buckets (including those previously missed like EFC 90/75/50 scores), edge cases for division by zero, handling of large numbers (trillions), and validating the logic flow for penalties and localization.

# Updated files:

## services/calculator.test.ts

Enhanced unit tests with complete coverage for all scoring tiers, large number handling, and edge case protection.

```typescript
import { calculateFinancialHealth } from './calculator';
import { FinancialInputs } from '../types';

// Fix for missing test runner type definitions
declare const describe: any;
declare const test: any;
declare const expect: any;

// Helper to create valid baseline data
const createInputs = (overrides: Partial<FinancialInputs> = {}): FinancialInputs => ({
  monthlyIncome: 20000000,
  monthlyExpenses: 10000000, // Net +10m
  cashAvailable: 60000000, // 6 months EFC
  monthlyDebtPayments: 2000000, // 10% DSR
  revenue: 100000000,
  payroll: 20000000, // 20%
  opCosts: 10000000,
  businessCashReserves: 200000000,
  cogs: 20000000,
  currentAssets: 50000000,
  currentLiabilities: 20000000, // 2.5 Ratio
  receivablesOver90: 0,
  totalReceivables: 10000000,
  topClientShare: 0.1, // 10%
  ...overrides
});

describe('calculateFinancialHealth', () => {

  describe('Cashflow Health (CFH)', () => {
    test('gives max score (100) for healthy surplus', () => {
      const inputs = createInputs({ monthlyIncome: 10000000, monthlyExpenses: 5000000 });
      const result = calculateFinancialHealth(inputs);
      expect(result.subScores.cfh.score).toBe(100);
      expect(result.metrics.netCashflow).toBe(5000000);
    });

    test('gives minimum score (40) for negative cashflow', () => {
      const inputs = createInputs({ monthlyIncome: 10000000, monthlyExpenses: 12000000 });
      const result = calculateFinancialHealth(inputs);
      expect(result.subScores.cfh.score).toBe(40);
      expect(result.subScores.cfh.status).toBe('warning');
    });

    test('handles zero income edge case gracefully', () => {
      const inputs = createInputs({ monthlyIncome: 0, monthlyExpenses: 5000000 });
      const result = calculateFinancialHealth(inputs);
      expect(result.subScores.cfh.score).toBe(40);
    });

    test('handles large numbers (Trillions)', () => {
      const inputs = createInputs({ monthlyIncome: 1000000000000, monthlyExpenses: 500000000000 });
      const result = calculateFinancialHealth(inputs);
      expect(result.subScores.cfh.score).toBe(100);
      expect(result.metrics.netCashflow).toBe(500000000000);
    });
  });

  describe('Debt Service Ratio (DSR)', () => {
    test('score 100 for DSR <= 20%', () => {
      const inputs = createInputs({ monthlyIncome: 10000000, monthlyDebtPayments: 1000000 }); // 10%
      const result = calculateFinancialHealth(inputs);
      expect(result.subScores.dsr.score).toBe(100);
    });

    test('calculates linear degradation for 20% < DSR <= 35%', () => {
      const inputs = createInputs({ monthlyIncome: 10000000, monthlyDebtPayments: 2750000 }); // 27.5%
      const result = calculateFinancialHealth(inputs);
      expect(result.subScores.dsr.score).toBeCloseTo(70, 0);
    });

    test('calculates linear degradation for 35% < DSR <= 50%', () => {
      const inputs = createInputs({ monthlyIncome: 10000000, monthlyDebtPayments: 4250000 }); // 42.5%
      const result = calculateFinancialHealth(inputs);
      expect(result.subScores.dsr.score).toBeCloseTo(45, 0);
    });

    test('returns 20 for DSR > 50% (Critical)', () => {
      const inputs = createInputs({ monthlyIncome: 10000000, monthlyDebtPayments: 6000000 }); // 60%
      const result = calculateFinancialHealth(inputs);
      expect(result.subScores.dsr.score).toBeLessThanOrEqual(20);
    });

    test('handles zero income for DSR (avoid division by zero)', () => {
      const inputs = createInputs({ monthlyIncome: 0, monthlyDebtPayments: 1000000 });
      const result = calculateFinancialHealth(inputs);
      // DSR = 1000000 / 1 = 1000000 (huge). Score should be min.
      expect(result.subScores.dsr.score).toBe(20);
    });
  });

  describe('Emergency Fund Coverage (EFC)', () => {
    test('score 100 for >= 12 months', () => {
      expect(calculateFinancialHealth(createInputs({ monthlyExpenses: 5000, cashAvailable: 60000 })).subScores.efc.score).toBe(100);
    });

    test('score 90 for 9-11 months', () => {
      expect(calculateFinancialHealth(createInputs({ monthlyExpenses: 1000, cashAvailable: 10000 })).subScores.efc.score).toBe(90);
    });

    test('score 75 for 6-8 months', () => {
      expect(calculateFinancialHealth(createInputs({ monthlyExpenses: 1000, cashAvailable: 7000 })).subScores.efc.score).toBe(75);
    });

    test('score 50 for 3-5 months', () => {
      expect(calculateFinancialHealth(createInputs({ monthlyExpenses: 1000, cashAvailable: 4000 })).subScores.efc.score).toBe(50);
    });

    test('score 30 for 1-3 months', () => {
      expect(calculateFinancialHealth(createInputs({ monthlyExpenses: 5000, cashAvailable: 10000 })).subScores.efc.score).toBe(30);
    });

    test('score 10 for < 1 month', () => {
      expect(calculateFinancialHealth(createInputs({ monthlyExpenses: 5000, cashAvailable: 2500 })).subScores.efc.score).toBe(10);
      expect(calculateFinancialHealth(createInputs({ monthlyExpenses: 5000, cashAvailable: 2500 })).subScores.efc.status).toBe('critical');
    });

    test('handles zero expenses edge case', () => {
       // Avoid infinity, should probably cap score at 100
       const inputs = createInputs({ monthlyExpenses: 0, cashAvailable: 100 });
       const result = calculateFinancialHealth(inputs);
       expect(result.subScores.efc.score).toBe(100);
    });
  });

  describe('Business Runway', () => {
    test('infinite runway (100) when burn is zero or negative', () => {
      const inputs = createInputs({ revenue: 100, cogs: 20, payroll: 20, opCosts: 10 });
      const result = calculateFinancialHealth(inputs);
      expect(result.subScores.runway.score).toBe(100);
      expect(result.metrics.monthlyBurn).toBe(0);
    });

    test('score 100 for >= 12 months runway', () => {
       const inputs = createInputs({ revenue: 0, cogs: 0, payroll: 1000, opCosts: 0, businessCashReserves: 13000 });
       // Burn 1000, Reserves 13000 -> 13 months
       expect(calculateFinancialHealth(inputs).subScores.runway.score).toBe(100);
    });

    test('score 75 for 6-12 months runway', () => {
        const inputs = createInputs({ revenue: 0, cogs: 0, payroll: 1000, opCosts: 0, businessCashReserves: 8000 });
        // 8 months
        expect(calculateFinancialHealth(inputs).subScores.runway.score).toBe(75);
    });

    test('score 50 for 3-6 months runway', () => {
        const inputs = createInputs({ revenue: 0, cogs: 0, payroll: 1000, opCosts: 0, businessCashReserves: 5000 });
        // 5 months
        expect(calculateFinancialHealth(inputs).subScores.runway.score).toBe(50);
    });

    test('score 20 for < 3 months runway', () => {
      const inputs = createInputs({ revenue: 0, cogs: 0, payroll: 1000, opCosts: 0, businessCashReserves: 2000 });
      // 2 months
      expect(calculateFinancialHealth(inputs).subScores.runway.score).toBe(20);
    });
  });

  describe('Profitability & Efficiency', () => {
    test('Net Margin scoring buckets', () => {
      // 15%+ -> 100
      expect(calculateFinancialHealth(createInputs({ revenue: 100, cogs: 50, payroll: 10, opCosts: 10, monthlyDebtPayments: 10 })).subScores.profitability.score).toBe(100);
      // 10-15% -> 80
      expect(calculateFinancialHealth(createInputs({ revenue: 100, cogs: 50, payroll: 10, opCosts: 15, monthlyDebtPayments: 13 })).subScores.profitability.score).toBe(80); // Margin 12%
      // 5-10% -> 60
      expect(calculateFinancialHealth(createInputs({ revenue: 100, cogs: 50, payroll: 10, opCosts: 15, monthlyDebtPayments: 17 })).subScores.profitability.score).toBe(60); // Margin 8%
      // 0-5% -> 40
      expect(calculateFinancialHealth(createInputs({ revenue: 100, cogs: 50, payroll: 10, opCosts: 15, monthlyDebtPayments: 22 })).subScores.profitability.score).toBe(40); // Margin 3%
      // Loss -> 10
      expect(calculateFinancialHealth(createInputs({ revenue: 100, cogs: 120 })).subScores.profitability.score).toBe(10);
    });

    test('Payroll Efficiency scoring buckets', () => {
      // <= 20% -> 100
      expect(calculateFinancialHealth(createInputs({ revenue: 100, payroll: 15 })).subScores.payroll.score).toBe(100);
      // 20-35% -> 80
      expect(calculateFinancialHealth(createInputs({ revenue: 100, payroll: 30 })).subScores.payroll.score).toBe(80);
      // 35-50% -> 50
      expect(calculateFinancialHealth(createInputs({ revenue: 100, payroll: 45 })).subScores.payroll.score).toBe(50);
      // > 50% -> 20
      expect(calculateFinancialHealth(createInputs({ revenue: 100, payroll: 60 })).subScores.payroll.score).toBe(20);
    });
  });

  describe('Advanced Logic & Penalties', () => {
    test('Liquidity scoring (Current Ratio)', () => {
      // Ratio 1.5+ -> 100
      expect(calculateFinancialHealth(createInputs({ currentAssets: 160, currentLiabilities: 100 })).subScores.liquidity.score).toBe(100);
      // Ratio 1.2-1.5 -> 80
      expect(calculateFinancialHealth(createInputs({ currentAssets: 130, currentLiabilities: 100 })).subScores.liquidity.score).toBe(80);
      // Ratio 1.0-1.2 -> 60
      expect(calculateFinancialHealth(createInputs({ currentAssets: 110, currentLiabilities: 100 })).subScores.liquidity.score).toBe(60);
      // Ratio < 1.0 -> 30
      expect(calculateFinancialHealth(createInputs({ currentAssets: 90, currentLiabilities: 100 })).subScores.liquidity.score).toBe(30);
    });

    test('Handles zero liabilities for Current Ratio (avoid division by zero)', () => {
       const inputs = createInputs({ currentAssets: 100, currentLiabilities: 0 });
       const result = calculateFinancialHealth(inputs);
       // Division by zero usually guarded by Math.max(1, ...). 100/1 = 100 ratio -> Score 100
       expect(result.subScores.liquidity.score).toBe(100);
    });

    test('Top Client Concentration Penalty', () => {
      const goodInputs = createInputs();
      const baseScore = calculateFinancialHealth(goodInputs).totalScore;

      const riskyInputs = createInputs({ topClientShare: 0.5 });
      const riskyResult = calculateFinancialHealth(riskyInputs);

      const hasWarning = riskyResult.actionPlan.some(a => a.title.includes('Diversify') || a.title.includes('Klien') || a.priorityCode === 'strategic');
      expect(hasWarning).toBe(true);
      expect(riskyResult.totalScore).toBeLessThan(baseScore);
    });
  });

  describe('Language Support', () => {
    test('returns English labels by default', () => {
      const result = calculateFinancialHealth(createInputs());
      expect(result.subScores.cfh.label).toBe('Cashflow Health');
    });

    test('returns Indonesian labels when requested', () => {
      const result = calculateFinancialHealth(createInputs(), 'id');
      expect(result.subScores.cfh.label).toBe('Kesehatan Arus Kas');
      // Verify action plan is in ID
      if (result.actionPlan.length > 0) {
         // This depends on what action is triggered. 
         // Let's trigger a specific one, e.g. Negative Cashflow
         const badInputs = createInputs({ monthlyIncome: 1000, monthlyExpenses: 2000 });
         const badResult = calculateFinancialHealth(badInputs, 'id');
         expect(badResult.actionPlan[0].title).toBe('Hentikan Kebocoran Kas');
      }
    });
  });

});
